import { oneLine, stripIndent } from "common-tags"
import { isPlainObject } from "lodash"

const generateGTM = ({ id, environmentParamStr, dataLayerName }) => oneLine`
  (function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':
