    result += `window.dataLayer.push(${JSON.stringify(dataLayer.value)});`
  }

  return result
}

exports.onRenderBody = (
  { setHeadComponents, setPreBodyComponents, reporter },
  pluginOptions
) => {
  if (
    process.env.NODE_ENV === `production` ||
    pluginOptions.includeInDevelopment
