    const environmentParamStr =
      pluginOptions.gtmAuth && pluginOptions.gtmPreview
        ? oneLine`
      &gtm_auth=${pluginOptions.gtmAuth}&gtm_preview=${
            pluginOptions.gtmPreview
          }&gtm_cookies_win=x
    `
        : ``

    let defaultDataLayer
    if (pluginOptions.defaultDataLayer) {
      defaultDataLayer = generateDefaultDataLayer(
        pluginOptions.defaultDataLayer,
        reporter
      )
    }

    const gtmScript = generateGTM({
      id: pluginOptions.id,
      environmentParamStr,
      dataLayerName: pluginOptions.dataLayerName || `dataLayer`,
    })

    setHeadComponents([
      <script
        key="plugin-google-tagmanager"
        dangerouslySetInnerHTML={{
          __html: oneLine`
            ${defaultDataLayer ? defaultDataLayer : ``}
          `.concat(gtmScript),
        }}
      />,
    ])

    setPreBodyComponents([
      <noscript
        key="plugin-google-tagmanager"
        dangerouslySetInnerHTML={{
          __html: generateGTMIframe({
            id: pluginOptions.id,
            environmentParamStr,
          }),
        }}
      />,
    ])
  }
}
